&lt;p id=&quot;p-rc_ed609c6a5ee7893e-256&quot; data-path-to-node=&quot;6,6,0&quot;&gt;&lt;span data-path-to-node=&quot;6,6,0,0&quot;&gt;Monitor, troubleshoot, and optimise pipeline performance to continuously improve efficiency and operational resilience&lt;/span&gt;&lt;span data-path-to-node=&quot;6,6,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;6,6,0,2&quot;&gt;.&lt;/span&gt; &lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p id=&quot;p-rc_ed609c6a5ee7893e-257&quot; data-path-to-node=&quot;6,7,0&quot;&gt;&lt;span data-path-to-node=&quot;6,7,0,0&quot;&gt;Participate in code reviews and actively contribute to continuous improvements in team engineering standards&lt;/span&gt;&lt;span data-path-to-node=&quot;6,7,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;6,7,0,2&quot;&gt;.&lt;/span&gt; &lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p id=&quot;p-rc_ed609c6a5ee7893e-258&quot; data-path-to-node=&quot;6,8,0&quot;&gt;&lt;span data-path-to-node=&quot;6,8,0,0&quot;&gt;Produce clear documentation and foster knowledge sharing across the data engineering craft&lt;/span&gt;&lt;span data-path-to-node=&quot;6,8,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;6,8,0,2&quot;&gt;.&lt;/span&gt; &lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-path-to-node=&quot;7&quot;&gt;&lt;strong data-path-to-node=&quot;7&quot; data-index-in-node=&quot;0&quot;&gt;What We’re Looking For:&lt;/strong&gt;&lt;/p&gt;
&lt;p data-path-to-node=&quot;8&quot;&gt;&lt;em data-path-to-node=&quot;8&quot; data-index-in-node=&quot;0&quot;&gt;Essential&lt;/em&gt;&lt;/p&gt;
&lt;ul data-path-to-node=&quot;9&quot;&gt;
&lt;li&gt;
&lt;p id=&quot;p-rc_ed609c6a5ee7893e-259&quot; data-path-to-node=&quot;9,0,0&quot;&gt;&lt;span data-path-to-node=&quot;9,0,0,0&quot;&gt;Proven experience developing ELT/ETL pipelines and working with data transformation frameworks such as dbt&lt;/span&gt;&lt;span data-path-to-node=&quot;9,0,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;9,0,0,2&quot;&gt;.&lt;/span&gt; &lt;/p&gt;
&lt;/li&gt;
