&lt;p id=&quot;p-rc_ed609c6a5ee7893e-260&quot; data-path-to-node=&quot;9,1,0&quot;&gt;&lt;span data-path-to-node=&quot;9,1,0,0&quot;&gt;Strong SQL skills and a solid understanding of programming fundamentals in Python, SQL, or standard query languages&lt;/span&gt;&lt;span data-path-to-node=&quot;9,1,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;9,1,0,2&quot;&gt;.&lt;/span&gt; &lt;/p&gt;
