&lt;li&gt;
&lt;p id=&quot;p-rc_ed609c6a5ee7893e-261&quot; data-path-to-node=&quot;9,2,0&quot;&gt;&lt;span data-path-to-node=&quot;9,2,0,0&quot;&gt;Hands-on experience using Git and CI/CD workflows&lt;/span&gt;&lt;span data-path-to-node=&quot;9,2,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;9,2,0,2&quot;&gt;.&lt;/span&gt; &lt;/p&gt;
